import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

/** The agent Worker never calls an LLM: answers are generated by the OCI runner. */
const ROOT = fileURLToPath(new URL("../../", import.meta.url));

function sources(dir: string): string[] {
  return readdirSync(join(ROOT, dir), { withFileTypes: true }).flatMap((entry) =>
    entry.isDirectory()
      ? sources(`${dir}/${entry.name}`)
      : entry.name.endsWith(".ts")
        ? [`${dir}/${entry.name}`]
        : [],
  );
}

describe("no LLM in the agent Worker", () => {
  it("has no AI binding or LLM secrets in wrangler.toml / .dev.vars.example", () => {
    for (const file of ["wrangler.toml", ".dev.vars.example"]) {
      const text = readFileSync(join(ROOT, file), "utf8");
      expect(text, file).not.toMatch(/^\s*\[\[?ai\]?\]/m);
      expect(text, file).not.toMatch(/GEMINI|OPENAI|ANTHROPIC|VERTEX|AI_GATEWAY/);
    }
  });

  it("imports no model SDK and calls no model API", () => {
    for (const file of sources("src")) {
      const text = readFileSync(join(ROOT, file), "utf8");
      expect(text, file).not.toMatch(/from "(ai|@ai-sdk\/[^"]+|openai|@google\/genai)"/);
      expect(text, file).not.toMatch(
        /generativelanguage\.googleapis|api\.openai\.com|aiplatform\.googleapis/,
      );
    }
  });
});
